<?php
require_once '../config.php';requireLogin();header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-cache, no-store, must-revalidate');
try{$uid=getUserId();$token=getAccessToken();$settings=sb_query('user_settings',['select'=>'setting_key,setting_value','user_id'=>'eq.'.$uid,'limit'=>100],$token);$map=[];foreach($settings as $s)$map[$s['setting_key']]=$s['setting_value'];$startDate=$map['study_start_date']??date('Y-m-d');$dailyLimit=max(1,min(200,(int)($map['daily_limit']??20)));$today=date('Y-m-d');$stats=sb_query('user_stats',['select'=>'stat_date,total_reviews','user_id'=>'eq.'.$uid,'order'=>'stat_date.desc','limit'=>366],$token);$activity=[];foreach($stats as $r)$activity[$r['stat_date']]=(int)$r['total_reviews'];$start=new DateTime($startDate);$now=new DateTime($today);$currentDay=max(1,$start->diff($now)->days+1);$yesterday=date('Y-m-d',strtotime('-1 day'));$broken=$currentDay>1&&(($activity[$yesterday]??0)===0&&($activity[$today]??0)===0);
if($broken){sb_update('user_settings',['user_id'=>$uid,'setting_key'=>'study_start_date'],['setting_value'=>$today],$token);$unfinished=sb_query('user_words',['select'=>'id','user_id'=>'eq.'.$uid,'learned'=>'eq.false','limit'=>1000],$token);foreach($unfinished as $w)sb_update('user_words',['id'=>$w['id'],'user_id'=>$uid],['ticks'=>0,'last_reviewed'=>null,'learned'=>false,'in_re_review'=>false,'review_history'=>[]],$token);$currentDay=1;}
$words=sb_query('user_words',['select'=>'id,english,farsi,ticks,learned,in_re_review,last_reviewed,review_history,date_added','user_id'=>'eq.'.$uid,'learned'=>'eq.false','order'=>'date_added.asc,id.asc','limit'=>1000],$token);$needed=min($currentDay*$dailyLimit,8*$dailyLimit);$selected=array_slice($words,0,$needed);$out=[];foreach($selected as $w){if(!empty($w['last_reviewed'])&&substr($w['last_reviewed'],0,10)===$today)continue;$ticks=(int)$w['ticks'];if($ticks>=6){sb_update('user_words',['id'=>$w['id'],'user_id'=>$uid],['learned'=>true],$token);continue;}$out[]=['id'=>(int)$w['id'],'english'=>$w['english'],'farsi'=>$w['farsi'],'ticks'=>$ticks,'learned'=>false,'inReReview'=>(bool)$w['in_re_review'],'history'=>is_array($w['review_history'])?$w['review_history']:[]];}
echo json_encode(['success'=>true,'currentDay'=>$currentDay,'wordsNeeded'=>$needed,'totalWords'=>count($out),'remainingWords'=>count($words),'streakBroken'=>$broken,'words'=>$out],JSON_UNESCAPED_UNICODE);
}catch(Throwable $e){echo json_encode(['success'=>false,'error'=>sb_error_message($e)],JSON_UNESCAPED_UNICODE);}
?>